        <span class="badge bg-primary rounded-pill ms-2">@items.Count</span>
    }
</h1>

@if (items is null)
{
    <p><em>Loading notifications…</em></p>
}
else if (items.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in items.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    // Persisted across prerender → interactive so we don't re-fetch.
    [PersistentState]
    public List<sv_7dcb844bbfc6476e855a864b51a44d75.Services.NotificationItem>? items { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // ??= means: only load if the property wasn't already restored from prerender state.
        items ??= await NotificationService.GetNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender never fires during prerender — safe to start polling here.
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        var lastSeenId = items?.LastOrDefault()?.Id ?? 0;

        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            // Simulate new notifications arriving in the service.
            NotificationService.SimulateIncoming();

            var newer = await NotificationService.GetNotificationsSinceAsync(lastSeenId);
            if (newer.Count > 0)
            {
                items ??= new();
                items.AddRange(newer);
                lastSeenId = newer[^1].Id;
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

